    90    static FT_Long
    91    cff_parse_integer( FT_Byte*  start,
    92                       FT_Byte*  limit )
    93    {
    94      FT_Byte*  p   = start;
    95      FT_Int    v   = *p++;
    96      FT_Long   val = 0;
    97
    98
    99      if ( v == 28 )
   100      {
   101        if ( p + 2 > limit )
   102          goto Bad;
   103
   104        val = (FT_Short)( ( (FT_UShort)p[0] << 8 ) | p[1] );
   105      }
   106      else if ( v == 29 )
   107      {
   108        if ( p + 4 > limit )
   109          goto Bad;
   110
   111        val = (FT_Long)( ( (FT_ULong)p[0] << 24 ) |
   112                         ( (FT_ULong)p[1] << 16 ) |
   113                         ( (FT_ULong)p[2] <<  8 ) |
   114                           (FT_ULong)p[3]         );
   115      }
   116      else if ( v < 247 )
   117      {
   118        val = v - 139;
   119      }
   120      else if ( v < 251 )
   121      {
   122        if ( p + 1 > limit )
   123          goto Bad;
   124
   125        val = ( v - 247 ) * 256 + p[0] + 108;
   126      }
   127      else
   128      {
   129        if ( p + 1 > limit )
   130          goto Bad;
   131
   132        val = -( v - 251 ) * 256 - p[0] - 108;
   133      }
   134
   135    Exit:
   136      return val;
   137
   138    Bad:
   139      val = 0;
   140      FT_TRACE4(( "!!!END OF DATA:!!!" ));
  1250    cff_parser_run( CFF_Parser  parser,
  1251                    FT_Byte*    start,
  1252                    FT_Byte*    limit )
  1253    {
  1254      FT_Byte*    p       = start;
  1255      FT_Error    error   = FT_Err_Ok;
  1256      FT_Library  library = parser->library;
  1257      FT_UNUSED( library );
  1258
  1259
  1260      parser->top    = parser->stack;
  1261      parser->start  = start;
  1262      parser->limit  = limit;
  1263      parser->cursor = start;
  1264
  1265      while ( p < limit )
  1266      {
  1267        FT_UInt  v = *p;
  1268
  1269        /* Opcode 31 is legacy MM T2 operator, not a number.      */
  1270        /* Opcode 255 is reserved and should not appear in fonts; */
  1271        /* it is used internally for CFF2 blends.                 */
  1272        if ( v >= 27 && v != 31 && v != 255 )
  1273        {
  1274          /* it's a number; we will push its position on the stack */
  1275          if ( (FT_UInt)( parser->top - parser->stack ) >= parser->stackSize )
  1276            goto Stack_Overflow;
  1277
  1278          *parser->top++ = p;
  1279
  1280          /* now, skip it */
  1281          if ( v == 30 )
  1282          {
  1283            /* skip real number */
  1284            p++;
  1285            for (;;)
  1286            {
  1287              /* An unterminated floating point number at the */
  1288              /* end of a dictionary is invalid but harmless. */
  1289              if ( p >= limit )
  1290                goto Exit;
  1291              v = p[0] >> 4;
  1292              if ( v == 15 )
  1293                break;
  1294              v = p[0] & 0xF;
  1295              if ( v == 15 )
  1296                break;
  1297              p++;
  1298            }
  1299          }
  1300          else if ( v == 28 )
  1301            p += 2;
  1302          else if ( v == 29 )
  1303            p += 4;
  1304          else if ( v > 246 )
  1305            p += 1;
  1306        }
  1307  #ifdef CFF_CONFIG_OPTION_OLD_ENGINE
  1308        else if ( v == 31 )
  1309        {
  1310          /* a Type 2 charstring */
  1311
  1312          CFF_Decoder  decoder;
  1313          CFF_FontRec  cff_rec;
  1314          FT_Byte*     charstring_base;
  1315          FT_ULong     charstring_len;
  1316
  1317          FT_Fixed*  stack;
  1318          FT_Byte*   q;
  1319
  1320
  1321          charstring_base = ++p;
  1322
  1323          /* search `endchar' operator */
  1324          for (;;)
  1325          {
  1326            if ( p >= limit )
  1327              goto Exit;
  1328            if ( *p == 14 )
  1329              break;
  1330            p++;
  1331          }
  1332
  1333          charstring_len = (FT_ULong)( p - charstring_base ) + 1;
  1334
  1335          /* construct CFF_Decoder object */
  1336          FT_ZERO( &decoder );
  1337          FT_ZERO( &cff_rec );
  1338
  1339          cff_rec.top_font.font_dict.num_designs = parser->num_designs;
  1340          cff_rec.top_font.font_dict.num_axes    = parser->num_axes;
  1341          decoder.cff                            = &cff_rec;
  1342
  1343          error = cff_decoder_parse_charstrings( &decoder,
  1344                                                 charstring_base,
  1345                                                 charstring_len,
  1346                                                 1 );
  1347
  1348          /* Now copy the stack data in the temporary decoder object,    */
  1349          /* converting it back to charstring number representations     */
  1350          /* (this is ugly, I know).                                     */
  1351          /*                                                             */
  1352          /* We overwrite the original top DICT charstring under the     */
  1353          /* assumption that the charstring representation of the result */
  1354          /* of `cff_decoder_parse_charstrings' is shorter, which should */
  1355          /* be always true.                                             */
  1356
  1357          q     = charstring_base - 1;
  1358          stack = decoder.stack;
  1359
  1360          while ( stack < decoder.top )
  1361          {
  1362            FT_ULong  num;
  1363            FT_Bool   neg;
  1364
  1365
  1366            if ( (FT_UInt)( parser->top - parser->stack ) >= parser->stackSize )
  1367              goto Stack_Overflow;
  1368
  1369            *parser->top++ = q;
  1370
  1371            if ( *stack < 0 )
  1372            {
  1373              num = (FT_ULong)-*stack;
  1374              neg = 1;
  1375            }
  1376            else
  1377            {
  1378              num = (FT_ULong)*stack;
  1379              neg = 0;
  1380            }
  1381
  1382            if ( num & 0xFFFFU )
  1383            {
  1384              if ( neg )
  1385                num = (FT_ULong)-num;
  1386
  1387              *q++ = 255;
  1388              *q++ = ( num & 0xFF000000U ) >> 24;
  1389              *q++ = ( num & 0x00FF0000U ) >> 16;
  1390              *q++ = ( num & 0x0000FF00U ) >>  8;
  1390              *q++ = ( num & 0x0000FF00U ) >>  8;
  1391              *q++ =   num & 0x000000FFU;
  1392            }
  1393            else
  1394            {
  1395              num >>= 16;
  1396
  1397              if ( neg )
  1398              {
  1399                if ( num <= 107 )
  1400                  *q++ = (FT_Byte)( 139 - num );
  1401                else if ( num <= 1131 )
  1402                {
  1403                  *q++ = (FT_Byte)( ( ( num - 108 ) >> 8 ) + 251 );
  1404                  *q++ = (FT_Byte)( ( num - 108 ) & 0xFF );
  1405                }
  1406                else
  1407                {
  1408                  num = (FT_ULong)-num;
  1409
  1410                  *q++ = 28;
  1411                  *q++ = (FT_Byte)( num >> 8 );
  1412                  *q++ = (FT_Byte)( num & 0xFF );
  1413                }
  1414              }
  1415              else
  1416              {
  1417                if ( num <= 107 )
  1418                  *q++ = (FT_Byte)( num + 139 );
  1419                else if ( num <= 1131 )
  1420                {
  1421                  *q++ = (FT_Byte)( ( ( num - 108 ) >> 8 ) + 247 );
  1422                  *q++ = (FT_Byte)( ( num - 108 ) & 0xFF );
  1423                }
  1424                else
  1425                {
  1426                  *q++ = 28;
  1427                  *q++ = (FT_Byte)( num >> 8 );
  1428                  *q++ = (FT_Byte)( num & 0xFF );
  1429                }
  1430              }
  1431            }
  1432
  1433            stack++;
  1434          }
  1435        }
  1436  #endif /* CFF_CONFIG_OPTION_OLD_ENGINE */
  1437        else
  1438        {
  1439          /* This is not a number, hence it's an operator.  Compute its code */
  1440          /* and look for it in our current list.                            */
  1441
  1442          FT_UInt                   code;
  1443          FT_UInt                   num_args;
  1444          const CFF_Field_Handler*  field;
