  1447          if ( (FT_UInt)( parser->top - parser->stack ) >= parser->stackSize )
  1448            goto Stack_Overflow;
  1449
  1450          num_args     = (FT_UInt)( parser->top - parser->stack );
  1451          *parser->top = p;
  1452          code         = v;
  1453
  1454          if ( v == 12 )
  1455          {
  1456            /* two byte operator */
  1457            p++;
  1458            if ( p >= limit )
  1459              goto Syntax_Error;
  1460
  1461            code = 0x100 | p[0];
  1462          }
