  1464
  1465          for ( field = CFF_FIELD_HANDLERS_GET; field->kind; field++ )
  1466          {
  1467            if ( field->code == (FT_Int)code )
  1468            {
  1469              /* we found our field's handler; read it */
  1470              FT_Long   val;
  1471              FT_Byte*  q = (FT_Byte*)parser->object + field->offset;
  1472
  1473
  1474  #ifdef FT_DEBUG_LEVEL_TRACE
  1475              FT_TRACE4(( "  %s", field->id ));
  1476  #endif
