  1478              /* check that we have enough arguments -- except for */
  1479              /* delta encoded arrays, which can be empty          */
  1480              if ( field->kind != cff_kind_delta && num_args < 1 )
  1481                goto Stack_Underflow;
  1482
  1483              switch ( field->kind )
  1484              {
  1485              case cff_kind_bool:
  1486              case cff_kind_string:
  1487              case cff_kind_num:
  1488                val = cff_parse_num( parser, parser->stack );
