  1490
  1491              case cff_kind_fixed:
  1492                val = cff_parse_fixed( parser, parser->stack );
  1493                goto Store_Number;
  1494
  1495              case cff_kind_fixed_thousand:
  1496                val = cff_parse_fixed_scaled( parser, parser->stack, 3 );
